create extension if not exists pgcrypto;
create table if not exists public.cities(id uuid primary key default gen_random_uuid(),name text not null,province text not null,country text not null default 'Argentina',slug text unique not null);
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,name text not null,avatar_url text,whatsapp text not null,email text,role text not null check(role in ('client','professional','admin')) default 'client',created_at timestamptz default now());
create table if not exists public.categories(id uuid primary key default gen_random_uuid(),name text unique not null,slug text unique not null,icon text,active boolean default true);
create table if not exists public.professional_profiles(id uuid primary key default gen_random_uuid(),user_id uuid unique references public.profiles(id) on delete cascade,city_id uuid references public.cities(id),trade text not null,description text,services text[] default '{}',zones text[] default '{}',radius_km numeric,years_experience int,works_at_home boolean default false,does_quotes boolean default false,hours text,available boolean default true,status text check(status in ('pending','approved','rejected','suspended')) default 'pending',rating numeric default 0,reviews_count int default 0,jobs_count int default 0,created_at timestamptz default now());
create table if not exists public.professional_categories(professional_id uuid references public.professional_profiles(id) on delete cascade,category_id uuid references public.categories(id) on delete cascade,primary key(professional_id,category_id));
create table if not exists public.portfolio_images(id uuid primary key default gen_random_uuid(),professional_id uuid references public.professional_profiles(id) on delete cascade,url text not null,sort_order int default 0);
create table if not exists public.service_requests(id uuid primary key default gen_random_uuid(),client_id uuid references public.profiles(id) on delete set null,city_id uuid references public.cities(id),category_id uuid references public.categories(id),title text not null,service text,description text,zone text,date_approx date,budget numeric,contact_method text,photo_urls text[] default '{}',status text default 'open',created_at timestamptz default now());
create table if not exists public.contact_events(id uuid primary key default gen_random_uuid(),professional_id uuid references public.professional_profiles(id) on delete cascade,request_id uuid references public.service_requests(id) on delete set null,source text default 'whatsapp',created_at timestamptz default now());
create table if not exists public.reviews(id uuid primary key default gen_random_uuid(),professional_id uuid references public.professional_profiles(id) on delete cascade,reviewer_id uuid references public.profiles(id) on delete set null,rating int check(rating between 1 and 5),comment text,request_id uuid references public.service_requests(id) on delete set null,status text default 'pending',created_at timestamptz default now());
create table if not exists public.reports(id uuid primary key default gen_random_uuid(),reporter_id uuid references public.profiles(id) on delete set null,professional_id uuid references public.professional_profiles(id) on delete cascade,request_id uuid references public.service_requests(id) on delete cascade,reason text not null,status text default 'open',created_at timestamptz default now());
create table if not exists public.verification_badges(id uuid primary key default gen_random_uuid(),professional_id uuid references public.professional_profiles(id) on delete cascade,badge_type text not null,verified boolean default false,verified_at timestamptz);
create table if not exists public.subscription_plans(id uuid primary key default gen_random_uuid(),name text not null,price numeric default 0,active boolean default false,features jsonb default '{}'::jsonb);
create table if not exists public.professional_subscriptions(id uuid primary key default gen_random_uuid(),professional_id uuid references public.professional_profiles(id) on delete cascade,plan_id uuid references public.subscription_plans(id),status text default 'inactive',starts_at timestamptz,ends_at timestamptz);
insert into public.cities(name,province,country,slug) values('Pergamino','Buenos Aires','Argentina','pergamino') on conflict(slug) do nothing;
insert into public.categories(name,slug,icon) values ('Construcción y reparaciones','construccion-reparaciones','🏠'),('Electricidad','electricidad','⚡'),('Gas','gas','🔥'),('Plomería','plomeria','🚰'),('Pintura','pintura','🎨'),('Carpintería','carpinteria','🪚'),('Herrería','herreria','🔩'),('Costura y confección','costura-confeccion','🧵'),('Jardinería','jardineria','🌱'),('Limpieza','limpieza','🧹'),('Belleza','belleza','💇'),('Automotor','automotor','🚗'),('Tecnología','tecnologia','📱'),('Mascotas','mascotas','🐶'),('Cuidado','cuidado','👶'),('Fletes y mudanzas','fletes-mudanzas','🚚'),('Cocina y repostería','cocina-reposteria','🍰'),('Otros servicios','otros-servicios','🛠️') on conflict(slug) do nothing;
-- RLS baseline: enable on all user data tables and add policies iteratively for production.
alter table public.profiles enable row level security; alter table public.professional_profiles enable row level security; alter table public.service_requests enable row level security; alter table public.reviews enable row level security; alter table public.reports enable row level security; alter table public.contact_events enable row level security;
create policy "public approved professionals" on public.professional_profiles for select using (status='approved');
create policy "users manage own profile" on public.profiles for all using (auth.uid()=id) with check(auth.uid()=id);
create policy "users create own professional profile" on public.professional_profiles for insert with check(user_id=auth.uid());
create policy "users update own professional profile" on public.professional_profiles for update using(user_id=auth.uid());
create policy "public open requests" on public.service_requests for select using(status='open');
create policy "authenticated create requests" on public.service_requests for insert with check(auth.uid()=client_id);
